dataSource.script:
return async function(config, ctx) {
  const apiUrl = String(config.apiUrl || '').trim();
  const token = String(config.token || '').trim();
  const mode = String(config.mode || 'standard');

  if (!apiUrl || !token) {
    return {
      options: [],
      help: 'required 未满足：请先填写 apiUrl + token',
      placeholder: '等待依赖字段满足后自动拉取'
    };
  }

  const options = mode === 'debug'
    ? [
        { label: 'Debug-Storage-A', value: 'dbg-a' },
        { label: 'Debug-Storage-B', value: 'dbg-b' }
      ]
    : [
        { label: 'Storage-1', value: 's1' },
        { label: 'Storage-2', value: 's2' }
      ];

  return {
    options,
    value: options[0].value,
    patch: {
      lockReason: mode === 'readonly' ? 'mode=readonly 时由 storageId.dataSource 自动回填' : ''
    },
    help: 'auto dataSource 已执行（watch: apiUrl, token, mode）',
    placeholder: '存储列表已自动更新'
  };
}

return async function(config, ctx) {
  const storageId = String(config.storageId || '').trim();
  if (!storageId) {
    return { options: [], help: 'required 未满足：请选择 storageId' };
  }

  return {
    options: [
      { label: storageId + '-album-1', value: storageId + '-a1' },
      { label: storageId + '-album-2', value: storageId + '-a2' }
    ],
    help: 'manual dataSource 已执行（仅点击按钮触发）'
  };
}

uploader.script:
return async function(config, file, ctx) {
  const summary = {
    mode: config.mode,
    apiUrl: config.apiUrl,
    tokenFilled: !!String(config.token || '').trim(),
    storageId: config.storageId,
    albumId: config.albumId,
    customLabels: config.customLabels,
    retryCount: config.retryCount,
    enableAdvanced: config.enableAdvanced,
    lockReason: config.lockReason,
    headers: config.headers,
    watermark: config.watermark
  };

  const fileName = file && file.name ? file.name : 'no-file';
  return 'https://plugin-test.local/upload/' + encodeURIComponent(fileName) + '?summary=' + encodeURIComponent(JSON.stringify(summary));
}
